package com.circlenet.domain.trust;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="emergency_access_approvals") @IdClass(EmergencyApprovalEntity.Key.class) public class EmergencyApprovalEntity {@Id @Column(name="request_id") private Long requestId;@Id @Column(name="approver_user_id") private Long approverUserId;@Column(nullable=false) private boolean approved;@Column(name="decided_at",nullable=false) private Instant decidedAt=Instant.now();public Long getRequestId(){return requestId;}public void setRequestId(Long v){requestId=v;}public Long getApproverUserId(){return approverUserId;}public void setApproverUserId(Long v){approverUserId=v;}public boolean isApproved(){return approved;}public void setApproved(boolean v){approved=v;}public Instant getDecidedAt(){return decidedAt;}public static class Key implements java.io.Serializable{public Long requestId;public Long approverUserId;public Key(){}public boolean equals(Object o){return o instanceof Key k&&java.util.Objects.equals(requestId,k.requestId)&&java.util.Objects.equals(approverUserId,k.approverUserId);}public int hashCode(){return java.util.Objects.hash(requestId,approverUserId);}}}
